static QString reports(const QString &prefix,int tag){QString text="Tag = "+QString::number(tag)+";\n";for(const auto &s:specs){const QString name=prefix+(s.hyperbolic?"Hyp":"Ell");text+="Vector = "+name+".EarthMJ2000Eq."+s.type+";\nReport Results Tag";for(int c=1;c<=6;++c)text+=" Vector("+QString::number(c)+",1)";for(const auto &field:s.components){const bool origin=QStringList{"SemilatusRectum","IncomingRadPer","IncomingC3Energy","OutgoingRadPer","OutgoingC3Energy","TA"}.contains(field);text+=" "+name+(origin?".Earth.":".EarthMJ2000Eq.")+field;}text+=";\n";}return text;}
